"""Robustness audit: how far can one measurement move before the centre does?

With two measurements held fixed, the median of three is the nearest-point
projection of the free measurement onto the segment they span. This script
audits that claim exactly (rational arithmetic) and quantifies robustness:

  * it sweeps the free measurement over a wide range and records the reported
    centre, showing the range is the compact segment and never leaves it;
  * it computes the exact stability set of the reported centre — the set of
    free values leaving it unchanged — and verifies it is the half-line
    (-inf, 224] for the measured data, refuting the informal threshold 256;
  * it verifies monotonicity, nonexpansiveness and firm nonexpansiveness;
  * it contrasts the median with the arithmetic mean, whose response to the
    free measurement is an unbounded affine map with slope 1/3.

Standard library only.  Run:  python3 robustness_audit.py
"""

from __future__ import annotations

from fractions import Fraction as F
from typing import List, Tuple

Num = F


def med3(a: Num, b: Num, c: Num) -> Num:
    """Median of three in (max, min) form."""
    return max(min(a, b), min(b, c), min(a, c))


def clamp(a: Num, b: Num, x: Num) -> Num:
    """Nearest-point projection of x onto the segment spanned by a and b."""
    return max(min(a, b), min(max(a, b), x))


def stability_set(a: Num, b: Num, target: Num) -> Tuple[str, str]:
    """Exact description of {x : med(a, b, x) = target} as an interval."""
    lo, hi = min(a, b), max(a, b)
    if target < lo or target > hi:
        return ("empty", "the target is outside the segment: unreachable")
    if target == lo:
        return (f"(-inf, {lo}]", "half-line: the normal cone at the lower endpoint")
    if target == hi:
        return (f"[{hi}, +inf)", "half-line: the normal cone at the upper endpoint")
    return (f"{{{target}}}", "singleton: interior points have singleton fibres")


def sweep(a: Num, b: Num, lo: int, hi: int, step: int) -> List[Tuple[Num, Num, Num]]:
    """Rows (free value, reported median, reported mean)."""
    out = []
    for k in range(lo, hi + 1, step):
        x = F(k)
        out.append((x, med3(a, b, x), (a + b + x) / 3))
    return out


def main() -> None:
    a, b = F(224), F(256)            # the two earlier measurements
    print(f"fixed measurements: {a}, {b}   -> segment [{min(a,b)}, {max(a,b)}]\n")

    rows = sweep(a, b, 80, 400, 32)
    print(f"{'free value':>11} | {'median':>8} | {'mean':>10} | centre moved?")
    print("-" * 56)
    for x, m, mu in rows:
        moved = "no" if m == F(224) else "YES"
        print(f"{str(x):>11} | {str(m):>8} | {float(mu):>10.2f} | {moved}")

    desc, why = stability_set(a, b, F(224))
    print(f"\nexact stability set of the reported centre 224: {desc}")
    print(f"  ({why})")
    print("  the measured free value 160 lies inside it, with infinite room below;")
    print("  the informal threshold '256' is wrong: 240 < 256 already moves the centre,")
    print(f"  since med(256, 224, 240) = {med3(F(256), F(224), F(240))}.")

    xs = [F(k, 2) for k in range(2 * 80, 2 * 400)]
    mono = all(clamp(a, b, xs[i]) <= clamp(a, b, xs[i + 1]) for i in range(len(xs) - 1))
    ne = all(abs(clamp(a, b, x) - clamp(a, b, y)) <= abs(x - y)
             for x in xs[::29] for y in xs[::31])
    fne = all((clamp(a, b, x) - clamp(a, b, y)) ** 2
              <= (x - y) * (clamp(a, b, x) - clamp(a, b, y))
              for x in xs[::29] for y in xs[::31])
    rng = (min(clamp(a, b, x) for x in xs), max(clamp(a, b, x) for x in xs))
    print(f"\nmonotone: {mono};  nonexpansive: {ne};  firmly nonexpansive: {fne}")
    print(f"range of the median over the sweep: [{rng[0]}, {rng[1]}]  (the compact segment)")
    print("range of the mean: unbounded — it is affine in the free value with slope 1/3,")
    print(f"  e.g. free value 10000 gives mean {float((a + b + F(10000)) / 3):.1f}.")

    excursion = abs(clamp(a, b, F(160)) - F(160))
    print(f"\nthe measured free value 160 sits {excursion} below the segment;")
    print("the projection absorbed the whole excursion and the reported centre moved by 0.")


if __name__ == "__main__":
    main()

